package main

import (
	"errors"
	"fmt"
	"testing"
)

// EmailSender interface
type EmailSender interface {
	Send(to, subject, body string) error
}

// NotificationService uses EmailSender
type NotificationService struct {
	sender EmailSender
}

func (n *NotificationService) NotifyUser(email, message string) error {
	if email == "" {
		return errors.New("email cannot be empty")
	}
	return n.sender.Send(email, "Notification", message)
}

// TODO: create MockEmailSender struct that implements EmailSender
// It should:
// - track SendCalls as a slice of structs with To, Subject, Body fields
// - support a ShouldFail bool field that makes Send return an error
type MockEmailSender struct {
	SendCalls  []string // store recipient emails
	ShouldFail bool
}

func (m *MockEmailSender) Send(to, subject, body string) error {
	if m.ShouldFail {
		return errors.New("smtp error")
	}
	m.SendCalls = append(m.SendCalls, to)
	return nil
}

func TestNotifyUser_Success(t *testing.T) {
	mock := &MockEmailSender{}
	svc := &NotificationService{sender: mock}

	err := svc.NotifyUser("user@example.com", "Hello!")
	if err != nil {
		t.Fatalf("unexpected error: %v", err)
	}
	if len(mock.SendCalls) != 1 {
		t.Errorf("expected 1 send call, got %d", len(mock.SendCalls))
	}
}

func main() {
	t := &testing.T{}
	TestNotifyUser_Success(t)
	fmt.Println("mock test passed")
}
